<script lang="ts">
  import IconButton from '../IconButton/IconButton.svelte';
  import IconWrapper from '../../internal/IconWrapper.svelte';
  import { t } from '../../services/translation.svelte.js';
  import { styleVariants } from '../../styles.js';
  import type { Color, IconLike, Shape, Size, TranslationProps } from '../../types.js';
  import { cleanClass } from '../../utilities/internal.js';
  import { mdiClose } from '@mdi/js';
  import type { Snippet } from 'svelte';
  import type { HTMLAttributes } from 'svelte/elements';
  import { tv } from 'tailwind-variants';

  type Props = {
    size?: Size;
    color?: Color;
    shape?: Shape;
    leadingIcon?: IconLike;
    trailingIcon?: IconLike;
    class?: string;
    translations?: TranslationProps<'close'>;
    onClose?: () => void;
    close?: Snippet;
    children?: Snippet;
  } & Omit<HTMLAttributes<HTMLSpanElement>, 'color'>;

  let {
    size = 'medium',
    class: className,
    color = 'primary',
    shape = 'semi-round',
    leadingIcon,
    trailingIcon,
    translations,
    onClose,
    close,
    children,
    ...props
  }: Props = $props();

  const styles = tv({
    base: 'inline-flex items-center gap-1 font-medium antialiased',
    variants: {
      shape: styleVariants.shape,
      color: {
        primary: 'bg-primary-100 text-primary-800 border border-primary-200',
        secondary: 'bg-light-100 text-light-800 border border-light-200',
        success: 'bg-success-100 text-success-700 border border-success-200',
        info: 'bg-info-100 text-info-800 border border-info-200',
        warning: 'bg-warning-100 text-warning-800 border border-warning-200',
        danger: 'bg-danger-100 text-danger-800 border border-danger-200',
      },
      textSize: styleVariants.textSize,
      paddingSize: {
        tiny: 'px-2 py-0.5',
        small: 'px-2.5 py-0.75',
        medium: 'px-2.5 py-1',
        large: 'px-3 py-1.25',
        giant: 'px-3.5 py-1.5',
      },
      roundedSize: {
        tiny: 'rounded-md',
        small: 'rounded-lg',
        medium: 'rounded-lg',
        large: 'rounded-xl',
        giant: 'rounded-xl',
      },
    },
  });
</script>

<span
  {...props}
  class={cleanClass(
    styles({
      color,
      textSize: size,
      paddingSize: size,
      shape,
      roundedSize: shape === 'semi-round' ? size : undefined,
    }),
    className,
  )}
>
  {#if leadingIcon}
    <IconWrapper {size} icon={leadingIcon} />
  {/if}
  {@render children?.()}
  {#if trailingIcon}
    <IconWrapper {size} icon={trailingIcon} />
  {/if}

  {#if onClose}
    <IconButton
      icon={mdiClose}
      {color}
      variant="ghost"
      size="tiny"
      aria-label={t('close', translations)}
      onclick={() => onClose()}
    />
  {/if}
  {#if close}
    {@render close()}
  {/if}
</span>
